-- Receipts are read by the owner, whoever keeps or checks the books, and the recovery
-- officer; written by the owner, an accountant and the recovery officer (the founder's
-- decision, 2026-11-14). A member limited to some branches has the receipts of those branches,
-- and none that belong to the whole company.
CREATE POLICY receipts_select ON public.receipts FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'recovery_officer')
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
  );
