-- ── hand-written: what may happen to a receipt ──────────────────────────────────────────────────
-- Whoever writes the row, the functions below included. A receipt starts as a draft with
-- nothing of a cheque's life on it. A posted one keeps everything it was posted with: only
-- where its cheque stands, and whether it has bounced or been cancelled, move on. A bounced or
-- cancelled one is final, and only a draft is removed. Only a session signed in as postgres
-- itself (a migration, or the removal of a synthetic test company) is not held to this. Who
-- may write a draft, and which of its columns, is for the grants and policies above.
CREATE FUNCTION app.check_receipt() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  -- What moves on after posting; everything else stays as it was posted.
  v_life text[] := ARRAY['status', 'account_id', 'bank_charges', 'cheque_status', 'deposited_on', 'cleared_on', 'bounced_on', 'bounce_reason',
    'clearance_journal_id', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by'];
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted receipt is never removed; cancel it instead' USING ERRCODE = 'SE104';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a receipt starts as a draft' USING ERRCODE = 'SE101';
    END IF;
    -- A draft carries nothing that only depositing, clearing or bouncing a cheque may write.
    NEW.deposited_on := NULL;
    NEW.cleared_on := NULL;
    NEW.clearance_journal_id := NULL;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
  END IF;
  IF OLD.status IN ('bounced', 'cancelled') THEN
    RAISE EXCEPTION 'a bounced or cancelled receipt is never changed' USING ERRCODE = 'SE104';
  END IF;
  -- A draft keeps its customer once it names invoices: they are that customer's.
  IF OLD.status = 'draft' AND NEW.customer_id <> OLD.customer_id AND EXISTS (
    SELECT 1 FROM public.receipt_allocations a WHERE a.tenant_id = OLD.tenant_id AND a.receipt_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'a receipt that names invoices keeps its customer' USING ERRCODE = 'SE102';
  END IF;
  IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'what a receipt is and who wrote it never change' USING ERRCODE = 'SE104';
  END IF;
  IF OLD.status = 'posted' THEN
    IF (to_jsonb(NEW) - v_life) IS DISTINCT FROM (to_jsonb(OLD) - v_life) THEN
      RAISE EXCEPTION 'a posted receipt is never changed; cancel it instead' USING ERRCODE = 'SE104';
    END IF;
    -- Where the money went is part of what was posted, except for a cheque, which says so when it is deposited.
    IF OLD.method <> 'cheque' AND (NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.bank_charges <> OLD.bank_charges) THEN
      RAISE EXCEPTION 'a posted receipt is never changed; cancel it instead' USING ERRCODE = 'SE104';
    END IF;
  END IF;
  -- Always later than what anyone read before this change, so a screen opened earlier can tell.
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_receipt() FROM PUBLIC;
