-- (Receipts already take a number: RC is among the kinds the product numbers.)

-- A receipt's journal stands with the posted receipt that names it; its reversal with a
-- receipt that has bounced or been cancelled.
CREATE FUNCTION app.journal_backed_receipt(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.receipts r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.journal_id = p_journal.id
        AND r.status <> 'draft' AND r.number = p_journal.document_number)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.reversal_backed_receipt(p_reversal public.journals, p_original public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.receipts r
      WHERE r.tenant_id = p_original.tenant_id AND r.journal_id = p_original.id AND r.status IN ('bounced', 'cancelled'))
  $$;
--> statement-breakpoint
-- The journal that takes a cleared cheque into the bank stands with the cheque that names it.
-- It is never reversed: it has no function for a reversal, so one is refused. A cheque that
-- bounces after it cleared comes back out of the bank with a journal of its own, which stands
-- with a bounced receipt that had cleared.
CREATE FUNCTION app.journal_backed_cheque_clearance(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.receipts r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.clearance_journal_id = p_journal.id
        AND r.method = 'cheque' AND r.cleared_on = p_journal.journal_date)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.journal_backed_cheque_return(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.receipts r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.method = 'cheque'
        AND r.status = 'bounced' AND r.clearance_journal_id IS NOT NULL AND r.bounced_on = p_journal.journal_date)
  $$;
--> statement-breakpoint
-- The journal that sets part of an advance against an invoice stands with the row that names
-- it; its reversal with a row that has stopped counting.
CREATE FUNCTION app.journal_backed_advance_application(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.receipt_allocations a
      WHERE a.tenant_id = p_journal.tenant_id AND a.id = p_journal.source_id AND a.journal_id = p_journal.id AND a.posted_at IS NOT NULL)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.reversal_backed_advance_application(p_reversal public.journals, p_original public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.receipt_allocations a
      WHERE a.tenant_id = p_original.tenant_id AND a.journal_id = p_original.id AND a.voided_at IS NOT NULL)
  $$;
