-- ── hand-written: what a customer has been billed, and what has been paid of it ─────────────────
-- Not for the app to call. Every posted invoice of a customer, and every unpaid invoice
-- brought in with the opening balances that stand, with what the receipts that count have
-- paid of it. Every question about what is still owed on an invoice is asked here, so a later
-- step that settles invoices another way (a credit note) changes one place.
CREATE FUNCTION app.receivable_items(p_tenant uuid, p_customer uuid)
  RETURNS TABLE (kind text, id uuid, number text, document_date date, due_date date, branch_id uuid, total numeric, settled numeric)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT 'invoice'::text, d.id, d.number, d.document_date, coalesce(d.due_date, d.document_date), d.branch_id, d.total,
      coalesce((
        SELECT sum(a.amount) FROM public.receipt_allocations a
        WHERE a.tenant_id = d.tenant_id AND a.invoice_id = d.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL), 0)
    FROM public.sales_documents d
    WHERE d.tenant_id = p_tenant AND d.customer_id = p_customer AND d.kind = 'invoice' AND d.status = 'submitted'
    UNION ALL
    SELECT 'opening'::text, b.id, b.document_number, b.document_date, coalesce(b.due_date, b.document_date), NULL::uuid, b.debit,
      coalesce((
        SELECT sum(a.amount) FROM public.receipt_allocations a
        WHERE a.tenant_id = b.tenant_id AND a.opening_balance_id = b.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL), 0)
    FROM public.opening_balances b
    JOIN public.opening_entries e ON e.tenant_id = b.tenant_id AND e.id = b.opening_entry_id
    WHERE b.tenant_id = p_tenant AND b.customer_id = p_customer AND b.kind = 'receivable' AND e.status = 'posted'
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.receivable_items(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.receivable_items(uuid, uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- What a customer still has to pay, invoice by invoice, oldest due first; with p_all, the
-- invoices that are paid in full as well. For whoever records or reads receipts, and the
-- sales manager. It runs with the table owner's rights because the recovery officer does not
-- otherwise read invoices or the opening balances; so it first asks who is reading. A member
-- limited to some branches is shown those branches' invoices and no others, as everywhere
-- else: not another branch's, and not the opening balances, which belong to the whole company.
CREATE FUNCTION app.receivables_open(p_customer uuid, p_all boolean DEFAULT false)
  RETURNS TABLE (kind text, id uuid, number text, document_date date, due_date date, total numeric, settled numeric, outstanding numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'recovery_officer', 'sales_manager') THEN
    RAISE EXCEPTION 'not allowed to see what a customer has to pay' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN QUERY
    SELECT i.kind, i.id, i.number, i.document_date, i.due_date, i.total, i.settled, i.total - i.settled
    FROM app.receivable_items(v_tenant, p_customer) i
    WHERE (coalesce(p_all, false) OR i.total > i.settled)
      AND (v_scope IS NULL OR i.branch_id = ANY (v_scope))
    ORDER BY i.due_date, i.document_date, i.number;
END $$;
