-- The cash and bank accounts money can be received into, for whoever records or reads
-- receipts: the recovery officer does not otherwise read the chart of accounts.
CREATE FUNCTION app.receipt_accounts() RETURNS TABLE (id uuid, code text, name text, kind text)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'recovery_officer') THEN
    RAISE EXCEPTION 'not allowed to see the cash and bank accounts' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN QUERY
    SELECT a.id, a.code, a.name, a.control_type
    FROM public.accounts a
    WHERE a.tenant_id = v_tenant AND a.control_type IN ('cash', 'bank') AND NOT a.is_group AND a.archived_at IS NULL
    ORDER BY a.code;
END $$;
