-- What one receipt pays, row by row, with the number and date of each invoice: the recovery
-- officer reads receipts and what they pay, but not the invoices or the opening balances
-- themselves. To a member who may not read the receipt it says nothing.
CREATE FUNCTION app.receipt_paid(p_receipt uuid)
  RETURNS TABLE (id uuid, kind text, target_id uuid, number text, document_date date, amount numeric, allocated_on date, counts boolean, later boolean)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'recovery_officer') OR NOT EXISTS (
    SELECT 1 FROM public.receipts r
    WHERE r.tenant_id = v_tenant AND r.id = p_receipt AND (v_scope IS NULL OR r.branch_id = ANY (v_scope))
  ) THEN
    RETURN;
  END IF;
  RETURN QUERY
    SELECT a.id, CASE WHEN a.invoice_id IS NOT NULL THEN 'invoice' ELSE 'opening' END, coalesce(a.invoice_id, a.opening_balance_id),
           -- Someone who works across the company can put another branch's invoice, or an opening
           -- balance, on a branch's receipt. A member limited to that branch sees the amount, not which.
           CASE WHEN v_scope IS NULL OR d.branch_id = ANY (v_scope) THEN coalesce(d.number, b.document_number) END,
           CASE WHEN v_scope IS NULL OR d.branch_id = ANY (v_scope) THEN coalesce(d.document_date, b.document_date) END,
           a.amount, a.allocated_on, a.posted_at IS NOT NULL AND a.voided_at IS NULL, a.journal_id IS NOT NULL
    FROM public.receipt_allocations a
    LEFT JOIN public.sales_documents d ON d.tenant_id = a.tenant_id AND d.id = a.invoice_id
    LEFT JOIN public.opening_balances b ON b.tenant_id = a.tenant_id AND b.id = a.opening_balance_id
    WHERE a.tenant_id = v_tenant AND a.receipt_id = p_receipt
    ORDER BY a.created_at, coalesce(d.document_date, b.document_date), coalesce(d.number, b.document_number);
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.receipt_paid(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.receipt_paid(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: the parts the functions below share ───────────────────────────────────────────
-- Not for the app to call. The receipt's row, held for the rest of the transaction, for a
-- member who may record receipts; to anyone else, and outside a member's branches, it does not
-- exist.
CREATE FUNCTION app.hold_receipt(p_receipt uuid) RETURNS public.receipts
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_receipt public.receipts%ROWTYPE;
BEGIN
  IF v_tenant IS NULL OR app.current_user_id() IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'recovery_officer') THEN
    RAISE EXCEPTION 'this role cannot record receipts' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'receipts are posted in read committed transactions' USING ERRCODE = 'SE107';
  END IF;
  SELECT r.* INTO v_receipt FROM public.receipts r
    WHERE r.tenant_id = v_tenant AND r.id = p_receipt
    FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND (v_receipt.branch_id IS NULL OR NOT (v_receipt.branch_id = ANY (v_scope)))) THEN
    RAISE EXCEPTION 'no such receipt in this company' USING ERRCODE = 'SE100';
  END IF;
  RETURN v_receipt;
END $$;
--> statement-breakpoint
-- The account money goes into, checked: a cash account for cash, a bank account otherwise;
-- never a heading, never an archived account.
CREATE FUNCTION app.receipt_account(p_tenant uuid, p_account uuid, p_kind text) RETURNS uuid
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.accounts a
    WHERE a.tenant_id = p_tenant AND a.id = p_account AND a.control_type = p_kind AND NOT a.is_group AND a.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'the money goes into a % account that is in use; one that has been archived is restored first', p_kind USING ERRCODE = 'SE106';
  END IF;
  RETURN p_account;
END $$;
--> statement-breakpoint
-- Posts the opposite of one of a receipt's journals on a day, line for line. Returns the reversal.
CREATE FUNCTION app.reverse_receipt_journal(p_journal uuid, p_date date, p_memo text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_original public.journals%ROWTYPE;
  v_reversal uuid;
  v_lines integer;
  v_total numeric;
BEGIN
  SELECT j.* INTO v_original FROM public.journals j WHERE j.tenant_id = app.tenant_id() AND j.id = p_journal;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such journal to reverse' USING ERRCODE = 'SE100';
  END IF;
  IF p_date < v_original.journal_date THEN
    RAISE EXCEPTION 'a receipt is taken back on or after the day of everything it posted' USING ERRCODE = 'SE108';
  END IF;
  -- The balance, and the document behind the journal, are asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, reverses_journal_id, document_number, memo, branch_id, created_by)
    VALUES (v_original.tenant_id, p_date, 'reversal', v_original.id, v_original.id, NULL, left(p_memo, 500), v_original.branch_id, app.current_user_id())
    RETURNING id INTO v_reversal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id, supplier_id)
    SELECT l.tenant_id, v_reversal, l.line_no, l.account_id, l.credit, l.debit, l.description, l.customer_id, l.supplier_id
    FROM public.journal_lines l
    WHERE l.tenant_id = v_original.tenant_id AND l.journal_id = v_original.id;
  SELECT count(*), sum(l.debit) INTO v_lines, v_total FROM public.journal_lines l WHERE l.tenant_id = v_original.tenant_id AND l.journal_id = v_reversal;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_original.tenant_id, app.current_user_id(), app.tenant_role(), 'journal.reverse', 'journal', v_reversal,
      jsonb_build_object('date', p_date, 'reverses', v_original.id, 'source', v_original.source_type, 'reversesNumber', v_original.document_number, 'lines', v_lines, 'total', v_total::text));
  RETURN v_reversal;
END $$;
--> statement-breakpoint
-- The last word after anything is set against a customer's invoices: none of them is paid
-- more than it comes to. The checks before it look at each row as it is asked for; this looks
-- at the whole once the rows count, so no way of writing them gets an invoice overpaid.
CREATE FUNCTION app.require_not_overpaid(p_tenant uuid, p_customer uuid) RETURNS void
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_number text;
BEGIN
  SELECT i.number INTO v_number FROM app.receivable_items(p_tenant, p_customer) i WHERE i.settled > i.total LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'more would be paid of % than it comes to', v_number USING ERRCODE = 'SE102';
  END IF;
END $$;
--> statement-breakpoint
-- Takes back what a receipt posted, on a day: its own journal, and each that set part of its
-- advance against an invoice. Every row of what it paid stops counting, so the invoices are
-- unpaid again. Returns the numbers of those invoices. (A cheque that had cleared is first
-- brought back out of the bank by app.bounce_cheque, with a journal of its own.)
CREATE FUNCTION app.undo_receipt(p_receipt public.receipts, p_date date, p_memo text) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_journal uuid;
  v_freed text;
BEGIN
  FOR v_journal IN
    SELECT a.journal_id FROM public.receipt_allocations a
    WHERE a.tenant_id = p_receipt.tenant_id AND a.receipt_id = p_receipt.id AND a.journal_id IS NOT NULL AND a.voided_at IS NULL
    ORDER BY a.created_at, a.id
  LOOP
    PERFORM app.reverse_receipt_journal(v_journal, p_date, p_memo);
  END LOOP;
  PERFORM app.reverse_receipt_journal(p_receipt.journal_id, p_date, p_memo);
  SELECT string_agg(DISTINCT coalesce(d.number, b.document_number), ', ') INTO v_freed
    FROM public.receipt_allocations a
    LEFT JOIN public.sales_documents d ON d.tenant_id = a.tenant_id AND d.id = a.invoice_id
    LEFT JOIN public.opening_balances b ON b.tenant_id = a.tenant_id AND b.id = a.opening_balance_id
    WHERE a.tenant_id = p_receipt.tenant_id AND a.receipt_id = p_receipt.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL;
  UPDATE public.receipt_allocations a SET voided_at = now()
    WHERE a.tenant_id = p_receipt.tenant_id AND a.receipt_id = p_receipt.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL;
  RETURN v_freed;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_receipt(uuid), app.receipt_account(uuid, uuid, text), app.reverse_receipt_journal(uuid, date, text), app.require_not_overpaid(uuid, uuid),
    app.undo_receipt(public.receipts, date, text)
  FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_receipt(uuid), app.receipt_account(uuid, uuid, text), app.reverse_receipt_journal(uuid, date, text), app.require_not_overpaid(uuid, uuid),
