-- ── hand-written: posting a receipt ─────────────────────────────────────────────────────────────
-- One act of the database, whole or not at all: the receipt takes its number, what it pays
-- starts to count, and the journal described at the top of this file is posted. Refused: an
-- invoice that is not this customer's, is not posted, is dated after the receipt, or has less
-- left to pay than the receipt sets against it (SE102); more set against invoices than the
-- receipt holds (SE103); an account of the wrong kind (SE106); a date in a period that is
-- closed (SE001, SE002) or before the books opened (SE015).
--
-- Everything that changes what a customer owes takes its turn, customer by customer, with
-- invoices and orders (the same lock as drizzle/0018_sales_invoices.sql).
CREATE FUNCTION app.post_receipt(p_receipt uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.receipts%ROWTYPE := app.hold_receipt(p_receipt);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_customer text;
  v_debit uuid;
  v_allocated numeric;
  v_rows integer;
  v_wrong text;
  v_number text;
  v_journal uuid;
  v_line_no integer := 0;
BEGIN
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft receipt is posted' USING ERRCODE = 'SE101';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF v_doc.receipt_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  SELECT c.name INTO v_customer FROM public.customers c WHERE c.tenant_id = v_tenant AND c.id = v_doc.customer_id;
  IF v_doc.method = 'cheque' THEN
    v_debit := app.control_account(v_tenant, 'cheques_in_hand');
  ELSE
    v_debit := app.receipt_account(v_tenant, v_doc.account_id, v_doc.method);
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.receipt_date);
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_tenant::text || ':' || v_doc.customer_id::text, 0));
  -- Opening balances a receipt is being set against stay as they are until this is done.
  PERFORM 1 FROM public.opening_entries e
    WHERE e.tenant_id = v_tenant AND e.id IN (
      SELECT b.opening_entry_id FROM public.receipt_allocations a
      JOIN public.opening_balances b ON b.tenant_id = a.tenant_id AND b.id = a.opening_balance_id
      WHERE a.tenant_id = v_tenant AND a.receipt_id = v_doc.id)
    FOR SHARE;

  SELECT count(*), coalesce(sum(a.amount), 0) INTO v_rows, v_allocated FROM public.receipt_allocations a
    WHERE a.tenant_id = v_tenant AND a.receipt_id = v_doc.id;
  IF v_allocated > v_doc.amount THEN
    RAISE EXCEPTION 'the receipt is for %, and % is set against invoices', v_doc.amount, v_allocated USING ERRCODE = 'SE103';
  END IF;
  -- Each invoice named: this customer's, posted, dated on or before the receipt, with enough
  -- left to pay; and for a member limited to some branches, an invoice of one of them.
  SELECT coalesce(i.number, 'an invoice that is not this customer''s') INTO v_wrong
    FROM public.receipt_allocations a
    LEFT JOIN app.receivable_items(v_tenant, v_doc.customer_id) i
      ON ((i.kind = 'invoice' AND i.id = a.invoice_id) OR (i.kind = 'opening' AND i.id = a.opening_balance_id))
     AND (v_scope IS NULL OR i.branch_id = ANY (v_scope))
    WHERE a.tenant_id = v_tenant AND a.receipt_id = v_doc.id
      AND (i.id IS NULL OR a.amount > i.total - i.settled OR i.document_date > v_doc.receipt_date)
    LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'the receipt cannot pay that much of %: it is not a posted invoice of this customer dated on or before the receipt, or less is left to pay', v_wrong USING ERRCODE = 'SE102';
  END IF;

  v_number := app.next_document_number('RC', v_doc.receipt_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, v_doc.receipt_date, 'receipt', v_doc.id, v_number,
      left('Received from ' || v_customer || CASE v_doc.method WHEN 'cheque' THEN ' by cheque ' || v_doc.cheque_number WHEN 'cash' THEN ' in cash' ELSE ' into the bank' END, 500),
      v_doc.branch_id, v_user)
    RETURNING id INTO v_journal;
  v_line_no := v_line_no + 1;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, v_line_no, v_debit, v_doc.amount - CASE v_doc.method WHEN 'cheque' THEN 0 ELSE v_doc.bank_charges END, 0,
      CASE v_doc.method WHEN 'cheque' THEN 'Cheque ' || v_doc.cheque_number || ' in hand' ELSE 'Receipt ' || v_number END);
  IF v_doc.method <> 'cheque' AND v_doc.bank_charges > 0 THEN
    v_line_no := v_line_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'bank_charges'), v_doc.bank_charges, 0, 'Kept by the bank on receipt ' || v_number);
  END IF;
  IF v_allocated > 0 THEN
    v_line_no := v_line_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
      VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'ar'), 0, v_allocated, 'Receipt ' || v_number, v_doc.customer_id);
  END IF;
  IF v_doc.amount > v_allocated THEN
    v_line_no := v_line_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
      VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'customer_advances'), 0, v_doc.amount - v_allocated, 'Receipt ' || v_number || ', not yet set against an invoice', v_doc.customer_id);
  END IF;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', v_doc.receipt_date, 'source', 'receipt', 'sourceId', v_doc.id, 'number', v_number, 'lines', v_line_no, 'total', v_doc.amount::text));

  UPDATE public.receipt_allocations a SET posted_at = now(), allocated_on = v_doc.receipt_date
    WHERE a.tenant_id = v_tenant AND a.receipt_id = v_doc.id;
  -- Asked once more of the whole, now that these rows count: no invoice of this customer is
  -- paid more than it comes to, however the rows were written.
  PERFORM app.require_not_overpaid(v_tenant, v_doc.customer_id);
  UPDATE public.receipts r
    SET status = 'posted', number = v_number, journal_id = v_journal, posted_at = now(), posted_by = v_user,
        cheque_status = CASE v_doc.method WHEN 'cheque' THEN 'received' END, updated_by = v_user
    WHERE r.tenant_id = v_tenant AND r.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'receipt.post', 'receipt', v_doc.id,
      jsonb_build_object('number', v_number, 'date', v_doc.receipt_date, 'customer', v_customer, 'method', v_doc.method, 'amount', v_doc.amount::text,
        'bankCharges', v_doc.bank_charges::text, 'invoices', v_rows, 'setAgainstInvoices', v_allocated::text, 'advance', (v_doc.amount - v_allocated)::text,
        'cheque', v_doc.cheque_number, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_receipt(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_receipt(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: a cheque, from in hand to the bank ────────────────────────────────────────────
-- Deposited: the cheque is at the bank. It is still a cheque, so nothing is posted; the
-- receipt keeps which bank account it went to and when. Not before the date on the cheque.
CREATE FUNCTION app.deposit_cheque(p_receipt uuid, p_account uuid, p_date date) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.receipts%ROWTYPE := app.hold_receipt(p_receipt);
  v_user uuid := app.current_user_id();
BEGIN
  IF v_doc.status <> 'posted' OR v_doc.cheque_status IS DISTINCT FROM 'received' THEN
    RAISE EXCEPTION 'only a cheque that is in hand is deposited' USING ERRCODE = 'SE101';
  END IF;
  IF p_date IS NULL OR p_date < v_doc.receipt_date OR p_date < v_doc.cheque_date THEN
    RAISE EXCEPTION 'a cheque is deposited on or after the day it was received and the date written on it' USING ERRCODE = 'SE108';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  UPDATE public.receipts r SET cheque_status = 'deposited', account_id = app.receipt_account(v_doc.tenant_id, p_account, 'bank'), deposited_on = p_date, updated_by = v_user
    WHERE r.tenant_id = v_doc.tenant_id AND r.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'cheque.deposit', 'receipt', v_doc.id, jsonb_build_object('cheque', 'received'),
      jsonb_build_object('cheque', 'deposited', 'number', v_doc.number, 'chequeNumber', v_doc.cheque_number, 'date', p_date,
        'account', (SELECT a.code || ' ' || a.name FROM public.accounts a WHERE a.tenant_id = v_doc.tenant_id AND a.id = p_account)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.deposit_cheque(uuid, uuid, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.deposit_cheque(uuid, uuid, date) TO app_runtime;
--> statement-breakpoint

-- Cleared: the money has reached the bank account the cheque was deposited in. Posts
--
--   debit   the bank account      the cheque, less what the bank kept
--   debit   Bank charges          what the bank kept, if anything
--   credit  Cheques in hand       the cheque
--
-- on the day it cleared, which is on or after the day it was deposited.
CREATE FUNCTION app.clear_cheque(p_receipt uuid, p_date date, p_bank_charges numeric DEFAULT 0) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.receipts%ROWTYPE := app.hold_receipt(p_receipt);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_charges numeric := coalesce(p_bank_charges, 0);
  v_journal uuid;
  v_lines integer := 2;
BEGIN
  IF v_doc.status <> 'posted' OR v_doc.cheque_status IS DISTINCT FROM 'deposited' THEN
    RAISE EXCEPTION 'only a cheque that has been deposited is cleared' USING ERRCODE = 'SE101';
  END IF;
  IF p_date IS NULL OR p_date < v_doc.deposited_on THEN
    RAISE EXCEPTION 'a cheque clears on or after the day it was deposited' USING ERRCODE = 'SE108';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  -- An amount is a real number ("not a number" is a value numeric accepts) and is never rounded behind anyone's back.
  IF v_charges = 'NaN'::numeric OR v_charges < 0 OR v_charges >= v_doc.amount OR v_charges <> round(v_charges, 4) THEN
    RAISE EXCEPTION 'what the bank kept is nothing or more, less than the cheque, to at most four decimals' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_date, 'cheque_clearance', v_doc.id, NULL, left('Cheque ' || v_doc.cheque_number || ' of receipt ' || v_doc.number || ' cleared', 500), v_doc.branch_id, v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    -- The account it was deposited in. One archived since is refused here, in words that say
    -- what to do (restore it): the ledger takes no new line on an archived account.
    VALUES (v_tenant, v_journal, 1, app.receipt_account(v_tenant, v_doc.account_id, 'bank'), v_doc.amount - v_charges, 0, 'Cheque ' || v_doc.cheque_number || ' cleared');
  IF v_charges > 0 THEN
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, 2, app.control_account(v_tenant, 'bank_charges'), v_charges, 0, 'Kept by the bank on cheque ' || v_doc.cheque_number);
    v_lines := 3;
  END IF;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, v_lines, app.control_account(v_tenant, 'cheques_in_hand'), 0, v_doc.amount, 'Cheque ' || v_doc.cheque_number || ' cleared');
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'cheque_clearance', 'sourceId', v_doc.id, 'number', NULL, 'lines', v_lines, 'total', v_doc.amount::text));
  UPDATE public.receipts r SET cheque_status = 'cleared', cleared_on = p_date, clearance_journal_id = v_journal, bank_charges = v_charges, updated_by = v_user
    WHERE r.tenant_id = v_tenant AND r.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_tenant, v_user, v_role, 'cheque.clear', 'receipt', v_doc.id, jsonb_build_object('cheque', 'deposited'),
      jsonb_build_object('cheque', 'cleared', 'number', v_doc.number, 'chequeNumber', v_doc.cheque_number, 'date', p_date, 'bankCharges', v_charges::text, 'journalId', v_journal));
  RETURN v_journal;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.clear_cheque(uuid, date, numeric) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.clear_cheque(uuid, date, numeric) TO app_runtime;
--> statement-breakpoint

-- Bounced: the bank sent the cheque back, whether it was still in hand, deposited or already
-- cleared. One act of the database, whole or not at all: what the receipt posted is reversed
-- on the day given, and everything it paid stops counting, so the invoices are unpaid again
-- and what was an advance is gone. A cheque that had cleared first comes back out of the bank:
--
--   debit   Cheques in hand       the cheque, in full
--   credit  the bank account      the cheque, in full
--
-- which is what the bank does: it takes back the whole cheque and keeps what it charged for
-- collecting it. A bounced receipt is final; when the customer pays again, that is a new
-- receipt.
CREATE FUNCTION app.bounce_cheque(p_receipt uuid, p_date date, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.receipts%ROWTYPE := app.hold_receipt(p_receipt);
  v_user uuid := app.current_user_id();
  v_reason text := btrim(p_reason);
  v_freed text;
  v_journal uuid;
BEGIN
  IF v_doc.status <> 'posted' OR v_doc.method <> 'cheque' THEN
    RAISE EXCEPTION 'only a cheque that stands can bounce' USING ERRCODE = 'SE101';
  END IF;
  IF p_date IS NULL OR p_date < coalesce(v_doc.cleared_on, v_doc.deposited_on, v_doc.receipt_date) THEN
    RAISE EXCEPTION 'a cheque bounces on or after the last thing that happened to it' USING ERRCODE = 'SE108';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  IF v_reason IS NULL OR char_length(v_reason) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'say why the cheque bounced, in 3 to 300 characters' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app.require_open_period(v_doc.tenant_id, p_date);
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_doc.tenant_id::text || ':' || v_doc.customer_id::text, 0));
  IF v_doc.clearance_journal_id IS NOT NULL THEN
    -- It had cleared: the bank takes the whole cheque back out of the account, and the cheque
    -- is in hand again for the receipt's own journal to be reversed. What the bank kept for
    -- collecting it is not given back and stays where the clearance put it, in Bank charges.
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_doc.tenant_id, p_date, 'cheque_return', v_doc.id, NULL, left('Cheque ' || v_doc.cheque_number || ' of receipt ' || v_doc.number || ' returned by the bank: ' || v_reason, 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_doc.tenant_id, v_journal, 1, app.control_account(v_doc.tenant_id, 'cheques_in_hand'), v_doc.amount, 0, 'Cheque ' || v_doc.cheque_number || ' returned by the bank'),
             (v_doc.tenant_id, v_journal, 2, app.receipt_account(v_doc.tenant_id, v_doc.account_id, 'bank'), 0, v_doc.amount, 'Cheque ' || v_doc.cheque_number || ' returned by the bank');
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', p_date, 'source', 'cheque_return', 'sourceId', v_doc.id, 'number', NULL, 'lines', 2, 'total', v_doc.amount::text));
  END IF;
  v_freed := app.undo_receipt(v_doc, p_date, 'Cheque ' || v_doc.cheque_number || ' of receipt ' || v_doc.number || ' bounced: ' || v_reason);
  UPDATE public.receipts r SET status = 'bounced', cheque_status = 'bounced', bounced_on = p_date, bounce_reason = v_reason, updated_by = v_user
    WHERE r.tenant_id = v_doc.tenant_id AND r.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'cheque.bounce', 'receipt', v_doc.id, jsonb_build_object('status', 'posted', 'cheque', v_doc.cheque_status),
      jsonb_build_object('status', 'bounced', 'number', v_doc.number, 'chequeNumber', v_doc.cheque_number, 'date', p_date, 'reason', v_reason,
        'amount', v_doc.amount::text, 'unpaidAgain', v_freed));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.bounce_cheque(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.bounce_cheque(uuid, date, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: cancelling a receipt ──────────────────────────────────────────────────────────
-- For a receipt entered by mistake. One act of the database, whole or not at all: everything
-- it posted is reversed on the day given and everything it paid stops counting. A cheque is
-- cancelled only while it is still in hand; one that has gone to the bank clears or bounces.
CREATE FUNCTION app.cancel_receipt(p_receipt uuid, p_date date, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.receipts%ROWTYPE := app.hold_receipt(p_receipt);
  v_user uuid := app.current_user_id();
  v_reason text := btrim(p_reason);
  v_freed text;
BEGIN
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'only a posted receipt is cancelled' USING ERRCODE = 'SE101';
  END IF;
  IF v_doc.method = 'cheque' AND v_doc.cheque_status <> 'received' THEN
    RAISE EXCEPTION 'a cheque that has gone to the bank clears or bounces; it is not cancelled' USING ERRCODE = 'SE101';
  END IF;
  IF p_date IS NULL OR p_date < v_doc.receipt_date THEN
    RAISE EXCEPTION 'a receipt is cancelled on or after its own date' USING ERRCODE = 'SE108';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  IF v_reason IS NULL OR char_length(v_reason) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'say why the receipt is cancelled, in 3 to 300 characters' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app.require_open_period(v_doc.tenant_id, p_date);
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_doc.tenant_id::text || ':' || v_doc.customer_id::text, 0));
  v_freed := app.undo_receipt(v_doc, p_date, 'Receipt ' || v_doc.number || ' cancelled: ' || v_reason);
  UPDATE public.receipts r SET status = 'cancelled', cancelled_at = now(), cancelled_by = v_user, cancel_reason = v_reason, updated_by = v_user
    WHERE r.tenant_id = v_doc.tenant_id AND r.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'receipt.cancel', 'receipt', v_doc.id, jsonb_build_object('status', 'posted'),
      jsonb_build_object('status', 'cancelled', 'number', v_doc.number, 'date', p_date, 'reason', v_reason, 'amount', v_doc.amount::text, 'unpaidAgain', v_freed));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_receipt(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_receipt(uuid, date, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: setting an advance against invoices ───────────────────────────────────────────
-- What a posted receipt did not set against an invoice is the customer's advance. Part or all
-- of it is set against invoices later: p_allocations is a list of
--   {"invoice_id": ..., "amount": ...}  or  {"opening_balance_id": ..., "amount": ...}
-- Each becomes a row that counts from p_date, with a journal of its own:
--
--   debit   Advances from customers (the customer)
--   credit  Trade receivables (the customer)
--
-- Refused: more than is left of the advance (SE110), an invoice that cannot take it (SE102).
-- Returns how many invoices it was set against.
CREATE FUNCTION app.apply_receipt_advance(p_receipt uuid, p_date date, p_allocations jsonb) RETURNS integer
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.receipts%ROWTYPE := app.hold_receipt(p_receipt);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_left numeric;
  v_asked numeric;
  v_wrong text;
  v_row record;
  v_id uuid;
  v_journal uuid;
  v_count integer := 0;
BEGIN
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'an advance is set against invoices only while its receipt stands' USING ERRCODE = 'SE101';
  END IF;
  IF p_date IS NULL OR p_date < v_doc.receipt_date THEN
    RAISE EXCEPTION 'an advance is set against an invoice on or after the day it was received' USING ERRCODE = 'SE108';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  IF p_allocations IS NULL OR jsonb_typeof(p_allocations) <> 'array' OR jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'name between 1 and 200 invoices' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_allocations) AS x(value)
    WHERE jsonb_typeof(x.value) <> 'object'
       OR (nullif(x.value->>'invoice_id', '') IS NULL) = (nullif(x.value->>'opening_balance_id', '') IS NULL)
       OR (x.value->>'amount') IS NULL
       OR (x.value->>'amount')::numeric = 'NaN'::numeric OR (x.value->>'amount')::numeric <= 0 OR (x.value->>'amount')::numeric >= 1e16
       OR (x.value->>'amount')::numeric <> round((x.value->>'amount')::numeric, 4)
  ) OR (
    -- Compared as ids, not as text: the same id in capitals or in braces is the same invoice.
    SELECT count(*) <> count(DISTINCT coalesce(nullif(x.value->>'invoice_id', '')::uuid, nullif(x.value->>'opening_balance_id', '')::uuid))
    FROM jsonb_array_elements(p_allocations) AS x(value)
  ) THEN
    RAISE EXCEPTION 'each invoice is named once, with an amount above nothing to at most four decimals' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_tenant::text || ':' || v_doc.customer_id::text, 0));
  PERFORM 1 FROM public.opening_entries e
    WHERE e.tenant_id = v_tenant AND e.id IN (
      SELECT b.opening_entry_id FROM jsonb_array_elements(p_allocations) AS x(value)
      JOIN public.opening_balances b ON b.tenant_id = v_tenant AND b.id = nullif(x.value->>'opening_balance_id', '')::uuid)
    FOR SHARE;

  SELECT v_doc.amount - coalesce(sum(a.amount), 0) INTO v_left FROM public.receipt_allocations a
    WHERE a.tenant_id = v_tenant AND a.receipt_id = v_doc.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL;
  SELECT sum((x.value->>'amount')::numeric) INTO v_asked FROM jsonb_array_elements(p_allocations) AS x(value);
  IF v_asked > v_left THEN
    RAISE EXCEPTION '% is left of this advance, and % was asked for', v_left, v_asked USING ERRCODE = 'SE110';
  END IF;
  SELECT coalesce(i.number, 'an invoice that is not this customer''s') INTO v_wrong
    FROM jsonb_array_elements(p_allocations) AS x(value)
    LEFT JOIN app.receivable_items(v_tenant, v_doc.customer_id) i
      ON ((i.kind = 'invoice' AND i.id = nullif(x.value->>'invoice_id', '')::uuid) OR (i.kind = 'opening' AND i.id = nullif(x.value->>'opening_balance_id', '')::uuid))
     AND (v_scope IS NULL OR i.branch_id = ANY (v_scope))
    WHERE i.id IS NULL OR (x.value->>'amount')::numeric > i.total - i.settled OR i.document_date > p_date
    LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'the advance cannot pay that much of %: it is not a posted invoice of this customer dated on or before that day, or less is left to pay', v_wrong USING ERRCODE = 'SE102';
  END IF;

  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  FOR v_row IN
    SELECT nullif(x.value->>'invoice_id', '')::uuid AS invoice_id, nullif(x.value->>'opening_balance_id', '')::uuid AS opening_balance_id, (x.value->>'amount')::numeric AS amount, x.ordinality
    FROM jsonb_array_elements(p_allocations) WITH ORDINALITY AS x(value, ordinality)
    ORDER BY x.ordinality
  LOOP
    v_id := gen_random_uuid();
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, p_date, 'advance_application', v_id, NULL, left('Advance of receipt ' || v_doc.number || ' set against an invoice', 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
      VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, 'customer_advances'), v_row.amount, 0, 'Advance of receipt ' || v_doc.number, v_doc.customer_id),
             (v_tenant, v_journal, 2, app.control_account(v_tenant, 'ar'), 0, v_row.amount, 'Advance of receipt ' || v_doc.number, v_doc.customer_id);
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', p_date, 'source', 'advance_application', 'sourceId', v_id, 'number', NULL, 'lines', 2, 'total', v_row.amount::text));
    INSERT INTO public.receipt_allocations (id, tenant_id, receipt_id, invoice_id, opening_balance_id, amount, allocated_on, journal_id, posted_at, created_by)
      VALUES (v_id, v_tenant, v_doc.id, v_row.invoice_id, v_row.opening_balance_id, v_row.amount, p_date, v_journal, now(), v_user);
    v_count := v_count + 1;
  END LOOP;
  PERFORM app.require_not_overpaid(v_tenant, v_doc.customer_id);
  -- So that a screen opened before this can tell the receipt has moved on.
  UPDATE public.receipts r SET updated_by = v_user WHERE r.tenant_id = v_tenant AND r.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'receipt.apply_advance', 'receipt', v_doc.id,
      jsonb_build_object('number', v_doc.number, 'date', p_date, 'invoices', v_count, 'setAgainstInvoices', v_asked::text, 'leftOfAdvance', (v_left - v_asked)::text));
  RETURN v_count;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.apply_receipt_advance(uuid, date, jsonb) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.apply_receipt_advance(uuid, date, jsonb) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: opening balances that receipts have been set against stay ─────────────────────
-- Reversing the opening balances starts a new draft with new lines; a receipt set against one
-- of the old lines would be left paying an invoice that is no longer in the books. So the
-- reversal is refused while any receipt that counts is set against a line of the entry. The
-- receipts are cancelled first (docs/LATER.md, "From Step 15"). A trigger of this step's own
-- on the opening entries, as docs/PARALLEL.md has it; the entry's own guard is unchanged.
CREATE FUNCTION app.check_opening_not_received() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
BEGIN
  IF OLD.status = 'posted' AND NEW.status <> 'posted' AND EXISTS (
    SELECT 1 FROM public.receipt_allocations a
    JOIN public.opening_balances b ON b.tenant_id = a.tenant_id AND b.id = a.opening_balance_id
    WHERE a.tenant_id = OLD.tenant_id AND b.opening_entry_id = OLD.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL
  ) THEN
    RAISE EXCEPTION 'receipts have been set against these opening balances; cancel those receipts before reversing them' USING ERRCODE = 'SE109';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_opening_not_received() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER opening_entries_receipts_allocated
  BEFORE UPDATE ON public.opening_entries
  FOR EACH ROW EXECUTE FUNCTION app.check_opening_not_received();
--> statement-breakpoint
ALTER TABLE public.opening_entries ENABLE ALWAYS TRIGGER opening_entries_receipts_allocated;
